concepts.code:
CREATE INDEX tickets_created_idx ON tickets (created_at);

-- Served by a descent plus a leaf walk:
SELECT id FROM tickets WHERE created_at >= '2025-03-01' AND created_at < '2025-04-01';
SELECT id FROM tickets ORDER BY created_at DESC LIMIT 20;   -- backward walk, no sort

-- Where does a row live? (page, item)
SELECT ctid, id FROM tickets LIMIT 3;

EXPLAIN (ANALYZE, BUFFERS)
SELECT id, title FROM tickets WHERE org_id = 7 AND created_at >= '2025-03-01';
-- Read the plan bottom-up: node type, Index Cond vs Filter,
-- estimated rows vs actual rows, and buffers (pages) read.

-- Statistics the planner uses for selectivity:
ANALYZE tickets;
SELECT attname, n_distinct, most_common_vals
FROM pg_stats WHERE tablename = 'tickets';

CREATE INDEX tickets_org_created_cov ON tickets (org_id, created_at) INCLUDE (title);

-- Can be answered from the index alone:
SELECT created_at, title FROM tickets WHERE org_id = 7 ORDER BY created_at DESC LIMIT 20;

-- Uniqueness on the key only; id rides along:
CREATE UNIQUE INDEX users_email_key ON users (email) INCLUDE (id);

-- 2% of tickets are open; the queue only ever asks for open ones
CREATE INDEX tickets_open_queue_idx
  ON tickets (org_id, priority DESC, created_at)
  WHERE status = 'open';

-- One active subscription per user; any number of past ones
CREATE UNIQUE INDEX one_active_sub ON subscriptions (user_id) WHERE active;
INSERT INTO subscriptions (user_id, plan, active) VALUES (42, 'pro', true)
ON CONFLICT (user_id) WHERE active DO UPDATE SET plan = EXCLUDED.plan;

-- Case-insensitive uniqueness and a fast login lookup in one index
CREATE UNIQUE INDEX users_email_lower_key ON users (lower(email));

-- At most one NULL allowed (PostgreSQL 15+)
CREATE TABLE devices (serial text UNIQUE NULLS NOT DISTINCT);

-- Build without blocking writes, then promote to a constraint
CREATE UNIQUE INDEX CONCURRENTLY accounts_handle_idx ON accounts (handle);
ALTER TABLE accounts ADD CONSTRAINT accounts_handle_key UNIQUE USING INDEX accounts_handle_idx;

CREATE INDEX accounts_doc_gin  ON accounts USING gin (doc jsonb_path_ops);
CREATE INDEX tickets_tags_gin  ON tickets  USING gin (tags);
CREATE INDEX articles_fts_gin  ON articles USING gin (to_tsvector('english', body));

SELECT id FROM accounts WHERE doc @> '{"plan": "pro"}';      -- uses the GIN index
SELECT id FROM accounts WHERE doc->>'plan' = 'pro';           -- does not
SELECT id FROM tickets  WHERE tags @> ARRAY['urgent'];
SELECT id FROM articles WHERE to_tsvector('english', body) @@ to_tsquery('english', 'refund');

walkthrough.code:
CREATE INDEX CONCURRENTLY tickets_org_created_idx ON tickets (org_id, created_at);

EXPLAIN (ANALYZE, BUFFERS)
SELECT id, title FROM tickets
WHERE org_id = 7 AND created_at >= '2025-03-01' AND created_at < '2025-04-01';
-- Look for: Index Cond: ((org_id = 7) AND (created_at >= ...) AND (created_at < ...))
-- and no separate Filter line for either column.

SET enable_seqscan = off;   -- diagnosis only: "can this index be used?"
EXPLAIN (COSTS OFF) SELECT id FROM users WHERE lower(email) = 'ana@shop.io';
-- Seq Scan on users / Disabled: true / Filter: (lower(email) = ...)
-- => no usable index for lower(email)
RESET enable_seqscan;

EXPLAIN (ANALYZE) SELECT id FROM tickets WHERE status = 'open';
-- rows=50 estimated vs rows=40000 actual => run ANALYZE tickets

SET lock_timeout = '5s';
CREATE INDEX CONCURRENTLY IF NOT EXISTS tickets_assignee_idx ON tickets (assignee_id);

-- Did it finish valid?
SELECT c.relname, i.indisvalid
FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid
WHERE i.indrelid = 'tickets'::regclass;

-- Clean up a failed build and retry
DROP INDEX CONCURRENTLY IF EXISTS tickets_assignee_idx;

