CREATE OR REPLACE FUNCTION plan_of(q text) RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE r text; BEGIN FOR r IN EXECUTE 'EXPLAIN (COSTS OFF) ' || q LOOP RETURN NEXT r; END LOOP; END $$;
SET enable_seqscan = off;
CREATE TEMP TABLE probe (probe text, passed boolean, ids int[]);
INSERT INTO probe
SELECT 'lookup uses an index',
       bool_or(p LIKE '%Index Cond: (lower(email) =%'),
       (SELECT array_agg(id ORDER BY id) FROM users WHERE lower(email) = 'ana@shop.io')
FROM plan_of($q$SELECT id FROM users WHERE lower(email) = 'ana@shop.io'$q$) AS p;
DO $$ BEGIN
  BEGIN
    INSERT INTO users (id, email, name)
    SELECT 1000, CASE WHEN email = upper(email) THEN lower(email) ELSE upper(email) END, 'dup'
    FROM users ORDER BY id LIMIT 1;
    INSERT INTO probe VALUES ('other-case duplicate rejected', false, NULL);
  EXCEPTION WHEN unique_violation THEN
    INSERT INTO probe VALUES ('other-case duplicate rejected', true, NULL);
  END;
END $$;
SELECT probe, passed, ids FROM probe

